('1', 'BMW', '535i', 'bmw-535i-2015', '2015', '159900.00', '0.00', NULL, '90669', 'gasolina', 'automatico', 'Azul', 'BMW 535i M Sport 2015, motor 3.0 24v 6 cilindros, câmbio automático 8 velocidades, cor azul metálico. 90.669 km. Completo, revisado e com procedência comprovada.', 'disponivel', '1', NULL, NULL, NULL, NULL, '2026-05-30 22:54:58', '2026-05-30 22:54:58'),
('2', 'Mercedes-Benz', 'GLA 45 AMG', 'mercedes-benz-gla-45-amg-2015', '2015', '184900.00', '0.00', NULL, '63523', 'gasolina', 'automatico', 'Cinza', 'Mercedes-Benz GLA 45 AMG 2015, motor 2.0 turbo 381cv, câmbio automático 7 velocidades. 63.523 km, cor cinza. Esportivo, completo e impecável.', 'disponivel', '1', NULL, NULL, NULL, NULL, '2026-05-30 22:55:06', '2026-05-30 22:55:06'),
('3', 'MINI', 'Countryman', 'mini-countryman-2018', '2018', '129800.00', '0.00', NULL, '112751', 'gasolina', 'automatico', 'Preto', 'MINI Countryman Cooper S ALL4 2018, motor 2.0 Twin Power Turbo, câmbio automático Steptronic. 112.751 km, cor preto. Tração integral, completo.', 'disponivel', '0', NULL, NULL, NULL, NULL, '2026-05-30 22:55:13', '2026-05-30 22:55:13'),
('4', 'Fun Motors', 'Farmer 300', 'fun-motors-farmer-300-2025', '2025', '44900.00', '0.00', NULL, '1146', 'gasolina', 'manual', 'Laranja', 'Fun Motors Farmer 300 2025, buggy com motor 300cc, câmbio manual, cor laranja. Apenas 1.146 km rodados. Ideal para aventura e uso off-road.', 'disponivel', '0', NULL, NULL, NULL, NULL, '2026-05-30 22:55:15', '2026-05-30 22:55:15'),
('5', 'Nissan', 'Kicks', 'nissan-kicks-2019', '2019', '86800.00', '0.00', NULL, '111369', 'flex', 'cvt', 'Branco', 'Nissan Kicks 1.6 SL X-Tronic 2019, câmbio CVT, cor branco. 111.369 km. Versão top de linha, teto solar, multimídia, completo.', 'disponivel', '0', NULL, NULL, NULL, NULL, '2026-05-30 22:55:24', '2026-05-30 22:55:24'),
('6', 'Fiat', 'Mobi', 'fiat-mobi-2024', '2024', '59800.00', '0.00', NULL, '65781', 'flex', 'manual', 'Prata', 'Fiat Mobi Like 2024, motor 1.0 flex, câmbio manual, cor prata. 65.781 km. Ar-condicionado, travas e vidros elétricos, freios ABS, rádio USB, ISOFIX.', 'disponivel', '0', NULL, NULL, NULL, NULL, '2026-05-30 22:55:27', '2026-05-30 22:55:27'),
